function nav(){var sidebar=document.querySelector(".sidebar"),btn_sidebar=document.querySelector(".btn-sidebar"),offcanvas=document.querySelector(".offcanvas");btn_sidebar.classList.toggle("open"),sidebar.classList.toggle("open"),offcanvas.classList.toggle("open"),offcanvas.addEventListener("click",(function(){offcanvas.classList.remove("open"),btn_sidebar.classList.remove("open"),sidebar.classList.remove("open")}))}function carouselHandler(action,carouselId){var carousel=document.getElementById(carouselId),activeElement=carousel.querySelector(".default.active");if("next"===action){var ProxElement=activeElement.nextElementSibling||carousel.querySelector(".carousel-item:first-child");activeElement.classList.remove("active","slide-fade"),ProxElement.classList.add("active","slide-fade")}else if("prev"===action)if(console.log(activeElement),"home-1"==activeElement.id||"autoras-1"==activeElement.id)ProxElement=activeElement;else{var ProxElement=activeElement.previousElementSibling||carousel.querySelector(".carousel-item:last-child");activeElement.classList.remove("active"),ProxElement.classList.add("active")}}function creditos(modulo){window.location.href="/creditos"+modulo+".html"}